package imageKit

import (
	"fmt"
	"testing"
)

func TestGetBase64ImageExt(t *testing.T) {
	{
		base64Str := "data:image/jpg;base64,"
		ext, err := GetBase64ImageExt(base64Str)
		if err != nil {
			panic(err)
		}
		fmt.Println(ext)
	}
	{
		// 去掉了前面的 "data:image/jpg;base64,"
		base64Str := ""
		ext, err := GetBase64ImageExt(base64Str)
		if err != nil {
			panic(err)
		}
		fmt.Println(ext)
	}

	{
		base64Str := "data:image/png;base64,"
		ext, err := GetBase64ImageExt(base64Str)
		if err != nil {
			panic(err)
		}
		fmt.Println(ext)
	}
}
